<script setup>
import{computed,onMounted,reactive,ref}from"vue";import{call,canAccess}from"../api";import AppModal from"../components/AppModal.vue";
const data=reactive({connections:[],operations:[],rules:[],review_count:0}),options=reactive({entities:[],points:[],articles:[]}),loading=ref(true),error=ref(""),connectionOpen=ref(false),reviewOpen=ref(false),saving=ref(false);const connectionForm=reactive({}),reviewForm=reactive({});const canEdit=computed(()=>canAccess("finance.bank","Edit"));const money=v=>`${new Intl.NumberFormat("ru-RU",{minimumFractionDigits:2}).format(Number(v||0))} ₽`;const dt=v=>v?new Intl.DateTimeFormat("ru-RU",{dateStyle:"short",timeStyle:"short"}).format(new Date(String(v).replace(" ","T"))):"—";
async function load(){loading.value=true;try{Object.assign(data,await call("raspechatka.api.tochka.get_bank_workspace"));}catch(e){error.value=e.message;}finally{loading.value=false;}}async function init(){Object.assign(options,await call("raspechatka.api.finance.get_finance_options"));await load();}
function openConnection(){Object.assign(connectionForm,{connection_name:"Точка Банк",business_entity:options.entities[0]?.name||"",bank_name:"Точка",enabled:0,sync_mode:"Dry Run",sync_interval_minutes:15,overlap_days:2,client_id:"",client_secret:""});connectionOpen.value=true;}async function saveConnection(){saving.value=true;try{await call("raspechatka.api.tochka.save_connection",{data:JSON.stringify(connectionForm)},{method:"POST"});connectionOpen.value=false;await load();}catch(e){error.value=e.message;}finally{saving.value=false;}}
async function connect(row){try{const r=await call("raspechatka.api.tochka.begin_oauth",{connection:row.name},{method:"POST"});window.open(r.url,"_blank","noopener");await load();}catch(e){error.value=e.message;}}async function accounts(row){try{const r=await call("raspechatka.api.tochka.refresh_accounts",{connection:row.name},{method:"POST"});alert(`Получено счетов: ${r.received}, сопоставлено: ${r.matched}`);}catch(e){error.value=e.message;}}async function sync(row){try{await call("raspechatka.api.tochka.sync_now",{connection:row.name},{method:"POST"});alert("Синхронизация поставлена в очередь");}catch(e){error.value=e.message;}}
function review(row){Object.keys(reviewForm).forEach(k=>delete reviewForm[k]);Object.assign(reviewForm,row,{financial_article:"",business_point:"",result:"Approve"});reviewOpen.value=true;}async function classify(){saving.value=true;try{await call("raspechatka.api.tochka.classify_operation",{name:reviewForm.name,financial_article:reviewForm.financial_article,business_point:reviewForm.business_point,result:reviewForm.result},{method:"POST"});reviewOpen.value=false;await load();}catch(e){error.value=e.message;}finally{saving.value=false;}}onMounted(init);
</script>
<template><section class="page finance-page"><div class="page-heading"><div><div class="eyebrow">ФИНАНСЫ / ИНТЕГРАЦИИ</div><h1>Точка Банк</h1><p>Выписка, автоматическая классификация и очередь проверки</p></div><button v-if="canEdit" class="button button-primary" @click="openConnection">＋ Подключение</button></div><div class="bank-security-note"><span>●</span><div><b>Банк — первичный источник фактов</b><p>Исходные операции сохраняются без изменений. Секреты OAuth хранятся в зашифрованных полях Frappe и не попадают в код.</p></div></div><div class="bank-connections"><article v-for="row in data.connections" :key="row.name"><div><small>{{row.bank_name}}</small><h3>{{row.connection_name}}</h3><span>{{row.business_entity}}</span></div><span class="connection-status" :class="row.status.toLowerCase().replace(' ','-')">{{row.status}}</span><div class="connection-actions"><button class="button button-secondary" @click="connect(row)">Подключить OAuth</button><button class="button button-secondary" :disabled="row.status!=='Connected'" @click="accounts(row)">Получить счета</button><button class="button button-primary" :disabled="row.status!=='Connected'" @click="sync(row)">Синхронизировать</button></div></article><div v-if="!data.connections.length" class="empty-connection"><b>Банк ещё не подключён</b><span>Создайте подключение для каждого ИП. Начните с режима Dry Run.</span></div></div><div class="section-heading bank-heading"><div><div class="eyebrow">БАНКОВСКИЕ ОПЕРАЦИИ</div><h2>Очередь обработки</h2></div><span class="review-count">{{data.review_count}} требуют проверки</span></div><div class="table-shell"><div v-if="loading" class="table-message"><span class="loader"></span></div><div v-else-if="!data.operations.length" class="table-message"><strong>Операций пока нет</strong><span>После подключения и синхронизации здесь появится выписка.</span></div><table v-else><thead><tr><th>Дата</th><th>Контрагент</th><th>Назначение</th><th>Операция</th><th>Сумма</th><th>Статус</th><th></th></tr></thead><tbody><tr v-for="row in data.operations" :key="row.name" @click="row.processing_status==='Review'&&review(row)"><td>{{dt(row.posted_at)}}</td><td class="item-name">{{row.counterparty_name||'—'}}</td><td class="finance-purpose">{{row.purpose}}</td><td>{{row.direction==='Income'?'Приход':'Расход'}}</td><td class="number-cell">{{money(row.amount)}}</td><td><span class="document-state" :class="`bank-${row.processing_status.toLowerCase()}`">{{row.processing_status}}</span></td><td class="row-arrow">{{row.processing_status==='Review'?'→':''}}</td></tr></tbody></table></div><p v-if="error" class="form-error">{{error}}</p>
<AppModal v-if="connectionOpen" title="Подключение Точка Банка" @close="connectionOpen=false"><form class="editor-form"><div class="form-section"><div class="form-grid"><label class="span-2">Название<input v-model="connectionForm.connection_name" required/></label><label>ИП<select v-model="connectionForm.business_entity" required><option v-for="x in options.entities" :key="x.name" :value="x.name">{{x.short_name}}</option></select></label><label>Режим<select v-model="connectionForm.sync_mode"><option value="Dry Run">Dry Run — проверка</option><option value="Live">Live — работа</option></select></label><label>Client ID<input v-model="connectionForm.client_id" type="password" autocomplete="off"/></label><label>Client secret<input v-model="connectionForm.client_secret" type="password" autocomplete="off"/></label><label><input v-model="connectionForm.enabled" type="checkbox" :true-value="1" :false-value="0"/> Автосинхронизация</label></div></div></form><template #footer><span></span><div class="footer-actions"><button class="button button-secondary" @click="connectionOpen=false">Закрыть</button><button class="button button-primary" :disabled="saving" @click="saveConnection">Сохранить</button></div></template></AppModal>
<AppModal v-if="reviewOpen" title="Классификация операции" @close="reviewOpen=false"><div class="review-operation"><b>{{reviewForm.counterparty_name}}</b><strong>{{money(reviewForm.amount)}}</strong><p>{{reviewForm.purpose}}</p></div><div class="form-grid"><label class="span-2">Финансовая статья<select v-model="reviewForm.financial_article"><option value="">Не выбрана</option><option v-for="x in options.articles.filter(a=>a.article_type===(reviewForm.direction==='Income'?'Income':'Expense'))" :key="x.name" :value="x.name">{{x.article_name}}</option></select></label><label>Точка<select v-model="reviewForm.business_point"><option value="">Без точки</option><option v-for="x in options.points" :key="x.name" :value="x.name">{{x.point_name}}</option></select></label><label>Решение<select v-model="reviewForm.result"><option value="Approve">Провести</option><option value="Ignore">Не учитывать</option></select></label></div><template #footer><span></span><button class="button button-primary" :disabled="saving" @click="classify">Применить</button></template></AppModal></section></template>
